#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DataType {
    ScalarInt,
    ScalarFloat,
    ScalarComplex,
    ScalarBool,
    ScalarString,
    ArrayType,
    CompositeType,
    UnknownType,
}

/// Returns `true` if `rep` is one of the scalar variants:
/// ScalarInt, ScalarFloat, ScalarComplex, ScalarBool, or ScalarString.
/// Otherwise returns `false`.
fn issctype(rep: DataType) -> bool {
    use DataType::*;
    matches!(
        rep,
        ScalarInt | ScalarFloat | ScalarComplex | ScalarBool | ScalarString
    )
}

fn main() {
    // Positive cases
    assert!(issctype(DataType::ScalarInt));
    assert!(issctype(DataType::ScalarFloat));
    assert!(issctype(DataType::ScalarComplex));
    assert!(issctype(DataType::ScalarBool));
    assert!(issctype(DataType::ScalarString));

    // Negative cases
    assert!(!issctype(DataType::ArrayType));
    assert!(!issctype(DataType::CompositeType));
    assert!(!issctype(DataType::UnknownType));

    println!("All tests passed!");
}